public sealed class DmDiagnosticIdentity {
    public string Scope,Peer,Id;public long Lifetime;public bool Screen;
    public string Key {get{return Scope+"/peer:"+Peer+"/"+(Screen?"share:":"call:")+Id+"/lifetime:"+Lifetime;}}
    public static DmDiagnosticIdentity Select(DmDiagnosticInput i,string id){
        // The screen entry has an explicit namespace; colliding call/share IDs cannot switch ownership.
        if(id!=null&&id.StartsWith("share:",StringComparison.Ordinal)){id=id.Substring(6);return i.ScreenState!=0&&i.ScreenId==id?new DmDiagnosticIdentity{Scope=i.Scope,Peer=i.ScreenPeer,Id=i.ScreenId,Lifetime=i.ScreenLifetime,Screen=true}:null;}
        if(i.Voice!=null&&i.Voice.Active&&!String.IsNullOrEmpty(i.Voice.CallId)&&(String.IsNullOrEmpty(id)||id==i.Voice.CallId))return new DmDiagnosticIdentity{Scope=i.Scope,Peer=i.Voice.PeerId,Id=i.Voice.CallId,Lifetime=i.Voice.Lifetime};
        if(i.ScreenState!=0&&!String.IsNullOrEmpty(i.ScreenId)&&(String.IsNullOrEmpty(id)||id==i.ScreenId))return new DmDiagnosticIdentity{Scope=i.Scope,Peer=i.ScreenPeer,Id=i.ScreenId,Lifetime=i.ScreenLifetime,Screen=true};return null;
    }
}
public sealed class DmRaw {
    readonly Dictionary<string,string> values=new Dictionary<string,string>(StringComparer.Ordinal);public readonly string Text;
    public DmRaw(string raw){Text=ConnectionsSafeText.Clean(raw??"");foreach(string line in Text.Split('\n').Take(600)){int eq=line.IndexOf('=');if(eq>0&&!values.ContainsKey(line.Substring(0,eq)))values[line.Substring(0,eq)]=line.Substring(eq+1).Trim();}}
    public string Value(string key){string v;return values.TryGetValue(key,out v)&&v!=""?v:"N/A — Not instrumented";}
    public double? Number(string key){double n;return Double.TryParse(Value(key),NumberStyles.Float,CultureInfo.InvariantCulture,out n)&&!Double.IsNaN(n)&&!Double.IsInfinity(n)&&n>=0?(double?)n:null;}
    public bool Is(string key,string value){return Value(key)==value;}
}
